/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const RtgBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *RtgBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The next board after `after`, or the first for null: the machine's
    /// display. A board whose device has gone is passed over.
    pub fn NextBoard(self: *RtgBase, after: ?*rtg.RtgBoard) ?*rtg.RtgBoard {
        return libraries.call(self, LVO.NextBoard, Fn.NextBoard, .{after});
    }

    /// The board of that name ("rgb.0"), gone or not, or null.
    pub fn FindBoard(self: *RtgBase, board_name: [*:0]const u8) ?*rtg.RtgBoard {
        return libraries.call(self, LVO.FindBoard, Fn.FindBoard, .{board_name});
    }

    /// Fill in `info`, of which `size` bytes are there - pass
    /// @sizeOf(RtgBoardInfo). Returns the bytes written; check it before
    /// trusting a field near the end.
    pub fn GetBoardInfo(self: *RtgBase, board: *rtg.RtgBoard, info: *rtg.RtgBoardInfo, size: u32) u32 {
        return libraries.call(self, LVO.GetBoardInfo, Fn.GetBoardInfo, .{ board, info, size });
    }

    /// What a board that refreshes itself has been through. Same rule as
    /// GetBoardInfo. All zeroes for a board that counts nothing.
    pub fn GetBoardStats(self: *RtgBase, board: *rtg.RtgBoard, stats: *rtg.RtgBoardStats, size: u32) u32 {
        return libraries.call(self, LVO.GetBoardStats, Fn.GetBoardStats, .{ board, stats, size });
    }

    /// Something only this driver knows about (RTGCTRL_*), or
    /// RTGCTRL_RESET_STATS, which every board takes. RTGERR_NOT_SUPPORTED for
    /// one it does not know.
    pub fn BoardControl(self: *RtgBase, board: *rtg.RtgBoard, what: u32, value: isize) isize {
        return libraries.call(self, LVO.BoardControl, Fn.BoardControl, .{ board, what, value });
    }

    /// The number of the board's mode of exactly that size, refresh (in
    /// milli-Hertz) and format, or 0. RTG_ANY matches whatever, so all four
    /// RTG_ANY is the board's default mode.
    pub fn FindBoardMode(self: *RtgBase, board: *rtg.RtgBoard, width: u32, height: u32, refresh_mhz: u32, format: u32) u32 {
        return libraries.call(self, LVO.FindBoardMode, Fn.FindBoardMode, .{ board, width, height, refresh_mhz, format });
    }

    /// A buffer in the board's display memory, its rows aligned as the board
    /// asks. RTGBMF_DISPLAYABLE makes one the board can be shown. Null: a
    /// size of 0, a format this build does not know, a board with no display
    /// memory, or no room.
    pub fn AllocBitMap(self: *RtgBase, board: *rtg.RtgBoard, width: u32, height: u32, format: u32, flags: u32) ?*rtg.RtgBitMap {
        return libraries.call(self, LVO.AllocBitMap, Fn.AllocBitMap, .{ board, width, height, format, flags });
    }

    /// A buffer over memory the caller owns: the seven fields of a surface are
    /// read out of `described` and nothing is allocated. Null: no pixels, a
    /// size of 0, a pitch shorter than a row, a format this build does not
    /// know, or no memory.
    pub fn AttachBitMap(self: *RtgBase, board: *rtg.RtgBoard, described: *const rtg.RtgBitMap) ?*rtg.RtgBitMap {
        return libraries.call(self, LVO.AttachBitMap, Fn.AttachBitMap, .{ board, described });
    }

    /// Give a buffer back. Refused while the board is showing it. Null does
    /// nothing.
    pub fn FreeBitMap(self: *RtgBase, bitmap: ?*rtg.RtgBitMap) void {
        return libraries.call(self, LVO.FreeBitMap, Fn.FreeBitMap, .{bitmap});
    }

    /// Show that buffer, whole, in the mode the board is in - its default
    /// where it is in none; null shows nothing.
    pub fn ShowBitMap(self: *RtgBase, board: *rtg.RtgBoard, bitmap: ?*rtg.RtgBitMap) i32 {
        return libraries.call(self, LVO.ShowBitMap, Fn.ShowBitMap, .{ board, bitmap });
    }

    /// The buffer the board is showing, or null. Its first seven fields are a
    /// drawing surface.
    pub fn BoardDisplayBitMap(self: *RtgBase, board: *rtg.RtgBoard) ?*rtg.RtgBitMap {
        return libraries.call(self, LVO.BoardDisplayBitMap, Fn.BoardDisplayBitMap, .{board});
    }

    /// Wait for `frames` frames of the display to end; 0 is the next one.
    /// For the frames the board's driver says ended, RTGERR_TIMEOUT when
    /// they do not come within two frames' time each; by the clock on a
    /// board that says none. Not from interrupts.
    pub fn WaitVBlank(self: *RtgBase, board: *rtg.RtgBoard, frames: u32) i32 {
        return libraries.call(self, LVO.WaitVBlank, Fn.WaitVBlank, .{ board, frames });
    }

    /// Put the board in a power state: RTGPWR_ON, the picture shown;
    /// RTGPWR_BLANK, the picture black; RTGPWR_ASLEEP, the display asleep.
    /// Answers the state it is in then - RTGPWR_BLANK for a board that does
    /// not sleep by itself - or an error below 0. What is shown or drawn
    /// meanwhile is kept, and the backlight comes back as it was.
    pub fn SetBoardPower(self: *RtgBase, board: *rtg.RtgBoard, state: u32) i32 {
        return libraries.call(self, LVO.SetBoardPower, Fn.SetBoardPower, .{ board, state });
    }

    /// The backlight, 0 to 100, the right way round whatever the part does;
    /// the library keeps the value, and GetBoardInfo answers it.
    /// RTGERR_NOT_SUPPORTED without RTGBC_BRIGHTNESS.
    pub fn SetBoardBrightness(self: *RtgBase, board: *rtg.RtgBoard, percent: u32) i32 {
        return libraries.call(self, LVO.SetBoardBrightness, Fn.SetBoardBrightness, .{ board, percent });
    }

    /// The board's link carries this sound from now on - the monitor is sent
    /// what it needs to play the samples the sound's driver feeds the link -
    /// or none, for null. For the sound's driver. RTGERR_NOT_SUPPORTED
    /// without RTGBC_AUDIO, RTGERR_NO_MODE while the link is not up.
    pub fn SetBoardAudio(self: *RtgBase, board: *rtg.RtgBoard, format: ?*const rtg.RtgAudio) i32 {
        return libraries.call(self, LVO.SetBoardAudio, Fn.SetBoardAudio, .{ board, format });
    }

    /// Fill a rectangle, in the buffer's format, right-aligned. The rectangle
    /// is cut down to the buffer first; nothing of it inside is RTGERR_OK and
    /// no work. RTGERR_NOT_SUPPORTED unless the board's engine fills - the
    /// library does not draw.
    pub fn FillRect(self: *RtgBase, dest: *rtg.RtgBitMap, area: *const rtg.RtgRect, color: u32) i32 {
        return libraries.call(self, LVO.FillRect, Fn.FillRect, .{ dest, area, color });
    }

    /// Copy a rectangle. The two buffers may be one and the rectangles may
    /// overlap. Same rules as FillRect.
    pub fn CopyRect(self: *RtgBase, src: *rtg.RtgBitMap, dest: *rtg.RtgBitMap, copy: *const rtg.RtgCopy) i32 {
        return libraries.call(self, LVO.CopyRect, Fn.CopyRect, .{ src, dest, copy });
    }

    /// A one-bit shape in two colours. Same rules as FillRect.
    pub fn BlitTemplate(self: *RtgBase, dest: *rtg.RtgBitMap, area: *const rtg.RtgRect, shape: *const rtg.RtgTemplate) i32 {
        return libraries.call(self, LVO.BlitTemplate, Fn.BlitTemplate, .{ dest, area, shape });
    }

    /// A one-bit tile, anchored to the buffer. Same rules as FillRect.
    pub fn BlitPattern(self: *RtgBase, dest: *rtg.RtgBitMap, area: *const rtg.RtgRect, tile: *const rtg.RtgPattern) i32 {
        return libraries.call(self, LVO.BlitPattern, Fn.BlitPattern, .{ dest, area, tile });
    }

    /// Hold off the picture a flipped board makes of its buffers, until
    /// UnlockBitMap: what is written into a shown buffer between the two is
    /// on the glass whole or not at all. For a writer of whole rectangles
    /// that is not the board's engine. Nothing on a board that is not
    /// flipped.
    pub fn LockBitMap(self: *RtgBase, bitmap: *rtg.RtgBitMap) void {
        return libraries.call(self, LVO.LockBitMap, Fn.LockBitMap, .{bitmap});
    }

    /// Let the board make pictures again. By the task that locked, once for
    /// each LockBitMap.
    pub fn UnlockBitMap(self: *RtgBase, bitmap: *rtg.RtgBitMap) void {
        return libraries.call(self, LVO.UnlockBitMap, Fn.UnlockBitMap, .{bitmap});
    }

    /// Read the settings file - null: ENV:Sys/display.prefs - in place of
    /// what the library holds, and apply it to the boards there are. A line
    /// that cannot be read is passed over and said on the log, and the
    /// answer is then RTGERR_BAD_ARG; RTGERR_NO_FILE where the file is not
    /// there, which changes nothing. From a process.
    pub fn LoadBoardSettings(self: *RtgBase, path: ?[*:0]const u8) i32 {
        return libraries.call(self, LVO.LoadBoardSettings, Fn.LoadBoardSettings, .{path});
    }

    /// Write the settings the library holds as a file - null:
    /// ENV:Sys/display.prefs. From a process.
    pub fn SaveBoardSettings(self: *RtgBase, path: ?[*:0]const u8) i32 {
        return libraries.call(self, LVO.SaveBoardSettings, Fn.SaveBoardSettings, .{path});
    }

    /// The line in force for the board - the one for the monitor on it, else
    /// the one that names no monitor - into `settings`, of which `size`
    /// bytes are there: pass @sizeOf(RtgSettings). Returns the bytes
    /// written; a board with no line answers one whose flags are 0.
    pub fn GetBoardSettings(self: *RtgBase, board: *rtg.RtgBoard, settings: *rtg.RtgSettings, size: u32) u32 {
        return libraries.call(self, LVO.GetBoardSettings, Fn.GetBoardSettings, .{ board, settings, size });
    }

    /// Make `settings` the board's line for the monitor on it now, and apply
    /// at once what can be: brightness, mirror, the colour range, which
    /// board is first. The mode is the board's default from then on, which
    /// its display is put in when its first screen opens. RTGERR_BAD_ARG
    /// for a value out of its range.
    pub fn SetBoardSettings(self: *RtgBase, board: *rtg.RtgBoard, settings: *const rtg.RtgSettings) i32 {
        return libraries.call(self, LVO.SetBoardSettings, Fn.SetBoardSettings, .{ board, settings });
    }

    /// Whether a driver from the disk is bound to the device of that name
    /// (GetRtgDevices) from the next start on. RTGERR_NO_MEMORY without
    /// room for the line.
    pub fn SetRtgDeviceDriver(self: *RtgBase, device_name: [*:0]const u8, on: bool) i32 {
        return libraries.call(self, LVO.SetRtgDeviceDriver, Fn.SetRtgDeviceDriver, .{ device_name, on });
    }

    /// Load the display drivers in DEVS:gfxdrv/ that take a device of this
    /// machine no driver has, then bind the drivers as BindRtgDrivers does.
    /// A file is read for what it takes before it is loaded; a driver whose
    /// name is in ENVARC:Sys/display.trying did not come back from its last
    /// try and is passed over. Answers how many boards were made. From a
    /// process.
    pub fn LoadRtgDrivers(self: *RtgBase) u32 {
        return libraries.call(self, LVO.LoadRtgDrivers, Fn.LoadRtgDrivers, .{});
    }

    /// Give a buffer to another board, its handle the same: that board
    /// shows it and its engine draws into it from then on. The memory goes
    /// along where the new board can read it there; else the pixels are
    /// copied into memory of the new board's, and `pixels` and `pitch` of
